/** Parse an SSE byte stream into messages (per the HTML living standard). */
async function* readMessages(
  reader: ReadableStreamDefaultReader<Uint8Array>,
): AsyncGenerator<SSEMessage, void, undefined> {
  const decoder = new TextDecoder();
  let buffer = "";

  // Per-event accumulators (reset on each blank line)
  let dataLines: string[] = [];
  let eventType: string | undefined;
  let eventId: string | undefined;
  let eventRetry: number | undefined;

  const applyField = (line: string) => {
    const colonIdx = line.indexOf(":");
    let field: string;
    let val: string;
    if (colonIdx === -1) {
      field = line;
      val = "";
    } else {
      field = line.slice(0, colonIdx);
      val = line.slice(colonIdx + 1);
      // Remove single leading space from value per spec
      if (val.startsWith(" ")) val = val.slice(1);
    }
    switch (field) {
      case "data":
        dataLines.push(val);
        break;
      case "event":
        eventType = val;
        break;
      case "id":
        // Per spec: id field must not contain U+0000 NULL
        if (!val.includes("\0")) eventId = val;
        break;
      case "retry": {
        const ms = Number(val);
        if (Number.isInteger(ms) && ms >= 0) eventRetry = ms;
        break;
      }
      // Unknown fields are ignored per spec
    }
  };

  const take = (): SSEMessage | undefined => {
    const message =
      dataLines.length > 0
        ? { data: dataLines.join("\n"), event: eventType, id: eventId, retry: eventRetry }
        : undefined;
    dataLines = [];
    eventType = undefined;
    eventId = undefined;
    eventRetry = undefined;
    return message;
  };

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() ?? "";

    for (const rawLine of lines) {
      const line = rawLine.replace(/\r$/, "");
      // Blank line = dispatch event
      if (line === "") {
        const message = take();
        if (message) yield message;
        continue;
      }
      // Comment lines (keep-alive)
      if (line.startsWith(":")) continue;
      applyField(line);
    }
  }

  // Flush a final event that was not followed by a blank line
  const remaining = (buffer + decoder.decode()).replace(/\r$/, "");
  if (remaining !== "" && !remaining.startsWith(":")) applyField(remaining);
  const message = take();
  if (message) yield message;
}

